window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-de406d08ea7bca48"]={"versions": [{"id": "FIG-de406d08ea7bca48", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Strukturdiagramm / Instanziierungsdiagramm auf M1-Modellebene aus <code>AUTOSAR_TPS_SystemTemplate</code> (Kapitel <em>Signal to Service Translation</em> / <em>System Mapping</em>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation eines rein deklarativen Mappings zur Übersetzung zwischen Signal-basierter Kommunikation (Classic AUTOSAR COM / ISignal / ISignalGroup) und Service-orientierter Kommunikation (SOME/IP, DDS, Adaptive Platform) unter ausschließlicher Verwendung von <code>PassThroughSwConnector</code>-Elementen.</li>\n<li><strong>Architektur-Einordnung:</strong> Zeigt die modellseitige Entkopplung von Übersetzungslogik und Applikationscode. Anstelle einer dedizierten Gateway-/Translation-SW-C mit eigenen <code>RunnableEntity</code>-Instanzen wird die Transformationskapsel als Composition modelliert, deren Ein- und Ausgänge direkt durch BSW-Transformer bzw. Signal-to-Service-Translation-Engines im Basissoftware-Stack verarbeitet werden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kapselungskontext / Composite Element:</strong></li>\n<li><code>Signal Service Translation</code>: Repräsentiert die strukturelle Systemgrenze (typischerweise modelliert als <code>CompositionSwComponentType</code> oder aggregierendes Übersetzungselement).</li>\n<li><strong>Ports (Outer Ports):</strong></li>\n<li><code>R1</code>, <code>R2</code>: <code>RPortPrototype</code> (Required Outer Ports), fungieren als Eingangs-Ports für die zu übersetzenden Quelldaten.</li>\n<li><code>P1</code>, <code>P2</code>: <code>PPortPrototype</code> (Provided Outer Ports), fungieren als Ausgangs-Ports für die transformierten Zieldaten.</li>\n<li><strong>Konnektoren (<code>PassThroughSwConnector</code>):</strong></li>\n<li><code>ptc1</code>: Instanz von <code>PassThroughSwConnector</code></li>\n<li><code>requiredOuterPort: R1</code></li>\n<li><code>providedOuterPort: P1</code></li>\n<li><code>ptc2</code>: Instanz von <code>PassThroughSwConnector</code></li>\n<li><code>requiredOuterPort: R2</code></li>\n<li><code>providedOuterPort: P2</code></li>\n<li><em>Semantik:</em> Verbindet einen äußeren Required-Port direkt mit einem äußeren Provided-Port derselben Komposition, ohne interne <code>SwComponentPrototype</code>-Instanzen zu durchlaufen.</li>\n<li><strong>Schnittstellen & Datenelemente:</strong></li>\n<li><code>S/R Interface ifX</code>: <code>SenderReceiverInterface</code>, typisiert <code>R1</code> und <code>P1</code>. Enthält das aggregierte Datenelement <code>dataX</code> mit den Sub-Elementen/Feldern <code>{A, C}</code>.</li>\n<li><code>S/R Interface ifY</code>: <code>SenderReceiverInterface</code>, typisiert <code>R2</code> und <code>P2</code>. Enthält das Datenelement <code>dataY</code> mit dem Sub-Element/Feld <code>{B}</code>.</li>\n<li><strong>Transformations-Metadaten (<code>SignalServiceTranslationProps</code>):</strong></li>\n<li><code>SignalServiceTranslationProps X</code>: Konfigurationsklasse, referenziert/annotiert <code>ifX - dataX {A, C}</code> zur Festlegung von Serialisierungs-, Skalierungs-, Routing- und Packing-Regeln.</li>\n<li><code>SignalServiceTranslationProps Y</code>: Konfigurationsklasse, annotiert <code>ifY - dataY {B}</code> an Port <code>P2</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Datenfluss:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ingress:</strong> Empfang von Signalen/Events an den Required Outer Ports (<code>R1</code>, <code>R2</code>) aus dem Quellnetzwerk (z. B. CAN-PDU via COM oder SOME/IP-Event via BSW).</li>\n<li><strong>Translation & Transformation (BSW-Ebene):</strong> Die Durchleitung erfolgt über die logischen Pfade <code>ptc1</code> und <code>ptc2</code>. Es findet kein Kontextwechsel in eine Applikations-Task statt. Stattdessen triggert die BSW (z. B. PduR, SOME/IP-Transformer, Signal-to-Service-Engine) die konfigurierte Transformation gemäß <code>SignalServiceTranslationProps X/Y</code>.</li>\n<li><strong>Egress:</strong> Bereitstellung der transformierten Payload direkt an den Provided Outer Ports (<code>P1</code>, <code>P2</code>) zur Weiterleitung in das Zielnetzwerk bzw. an abnehmende SW-Cs.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Synchronizität & Scheduling:</strong> Vollständig ereignis- oder zyklusgetrieben innerhalb der BSW-Ausführungskontexte (<code>MainFunction</code>-Zyklen bzw. Rx-Indication-Routinen), wodurch RTE-Scheduling-Overhead für Zwischenkomponenten entfällt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Vermeidung von Boilerplate-SW-Cs:</strong> Entwickler müssen für reine 1:1- oder Signal-zu-Service-Mappings keine leeren C-Stubs bzw. Applikations-SW-Cs mit RTE-Ports und Runnables implementieren; die Generierung erfolgt direkt in BSW-Routingtabellen / Transformer-Pipelines.</li>\n<li><strong>Restriktion für <code>PassThroughSwConnector</code>:</strong> Normativ darf ein <code>PassThroughSwConnector</code> ausschließlich einen äußeren <code>RPortPrototype</code> mit einem äußeren <code>PPortPrototype</code> derselben Composition kurzschließen. Eine Verschaltung zweier gleichgerichteter Ports (R-R oder P-P) ist unzulässig (dafür sind <code>DelegationSwConnector</code>-Elemente vorgeschrieben).</li>\n<li><strong>Schnittstellen- und Typkompatibilität:</strong> Obwohl Ein- und Ausgangsport an denselben Konnektor gebunden sind, erlaubt die Zuordnung von <code>SignalServiceTranslationProps</code> das Überbrücken von Protokoll- und Repräsentationsunterschieden (z. B. Big-Endian vs. Little-Endian, Signal-Array vs. SOME/IP-Serialisierung). Generatoren validieren strikt, ob alle in den <code>SignalServiceTranslationProps</code> referenzierten Datenelemente in den beteiligten S/R-Interfaces existieren.</li>\n</ul>"}, {"id": "FIG-4bc59198b9b551de", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Strukturdiagramm / Instanziierungsdiagramm auf M1-Modellebene aus <code>AUTOSAR_TPS_SystemTemplate</code> (Kapitel <em>Signal to Service Translation</em> / <em>System Mapping</em>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation eines rein deklarativen Mappings zur Übersetzung zwischen Signal-basierter Kommunikation (Classic AUTOSAR COM / ISignal / ISignalGroup) und Service-orientierter Kommunikation (SOME/IP, DDS, Adaptive Platform) unter ausschließlicher Verwendung von <code>PassThroughSwConnector</code>-Elementen.</li>\n<li><strong>Architektur-Einordnung:</strong> Zeigt die modellseitige Entkopplung von Übersetzungslogik und Applikationscode. Anstelle einer dedizierten Gateway-/Translation-SW-C mit eigenen <code>RunnableEntity</code>-Instanzen wird die Transformationskapsel als Composition modelliert, deren Ein- und Ausgänge direkt durch BSW-Transformer bzw. Signal-to-Service-Translation-Engines im Basissoftware-Stack verarbeitet werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kapselungskontext / Composite Element:</strong></li>\n<li><code>Signal Service Translation</code>: Repräsentiert die strukturelle Systemgrenze (typischerweise modelliert als <code>CompositionSwComponentType</code> oder aggregierendes Übersetzungselement).</li>\n<li><strong>Ports (Outer Ports):</strong></li>\n<li><code>R1</code>, <code>R2</code>: <code>RPortPrototype</code> (Required Outer Ports), fungieren als Eingangs-Ports für die zu übersetzenden Quelldaten.</li>\n<li><code>P1</code>, <code>P2</code>: <code>PPortPrototype</code> (Provided Outer Ports), fungieren als Ausgangs-Ports für die transformierten Zieldaten.</li>\n<li><strong>Konnektoren (<code>PassThroughSwConnector</code>):</strong></li>\n<li><code>ptc1</code>: Instanz von <code>PassThroughSwConnector</code></li>\n<li><code>requiredOuterPort: R1</code></li>\n<li><code>providedOuterPort: P1</code></li>\n<li><code>ptc2</code>: Instanz von <code>PassThroughSwConnector</code></li>\n<li><code>requiredOuterPort: R2</code></li>\n<li><code>providedOuterPort: P2</code></li>\n<li><em>Semantik:</em> Verbindet einen äußeren Required-Port direkt mit einem äußeren Provided-Port derselben Komposition, ohne interne <code>SwComponentPrototype</code>-Instanzen zu durchlaufen.</li>\n<li><strong>Schnittstellen & Datenelemente:</strong></li>\n<li><code>S/R Interface ifX</code>: <code>SenderReceiverInterface</code>, typisiert <code>R1</code> und <code>P1</code>. Enthält das aggregierte Datenelement <code>dataX</code> mit den Sub-Elementen/Feldern <code>{A, C}</code>.</li>\n<li><code>S/R Interface ifY</code>: <code>SenderReceiverInterface</code>, typisiert <code>R2</code> und <code>P2</code>. Enthält das Datenelement <code>dataY</code> mit dem Sub-Element/Feld <code>{B}</code>.</li>\n<li><strong>Transformations-Metadaten (<code>SignalServiceTranslationProps</code>):</strong></li>\n<li><code>SignalServiceTranslationProps X</code>: Konfigurationsklasse, referenziert/annotiert <code>ifX - dataX {A, C}</code> zur Festlegung von Serialisierungs-, Skalierungs-, Routing- und Packing-Regeln.</li>\n<li><code>SignalServiceTranslationProps Y</code>: Konfigurationsklasse, annotiert <code>ifY - dataY {B}</code> an Port <code>P2</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Datenfluss:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ingress:</strong> Empfang von Signalen/Events an den Required Outer Ports (<code>R1</code>, <code>R2</code>) aus dem Quellnetzwerk (z. B. CAN-PDU via COM oder SOME/IP-Event via BSW).</li>\n<li><strong>Translation & Transformation (BSW-Ebene):</strong> Die Durchleitung erfolgt über die logischen Pfade <code>ptc1</code> und <code>ptc2</code>. Es findet kein Kontextwechsel in eine Applikations-Task statt. Stattdessen triggert die BSW (z. B. PduR, SOME/IP-Transformer, Signal-to-Service-Engine) die konfigurierte Transformation gemäß <code>SignalServiceTranslationProps X/Y</code>.</li>\n<li><strong>Egress:</strong> Bereitstellung der transformierten Payload direkt an den Provided Outer Ports (<code>P1</code>, <code>P2</code>) zur Weiterleitung in das Zielnetzwerk bzw. an abnehmende SW-Cs.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Synchronizität & Scheduling:</strong> Vollständig ereignis- oder zyklusgetrieben innerhalb der BSW-Ausführungskontexte (<code>MainFunction</code>-Zyklen bzw. Rx-Indication-Routinen), wodurch RTE-Scheduling-Overhead für Zwischenkomponenten entfällt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Regelwerks-Konformität:</strong> Die Modellierung demonstriert die Spezifikation eines Signal-to-Service-Mappings ohne Applikations-SW-C, indem ausschließlich <code>PassThroughSwConnector</code>-Elemente auf Kompositionsebene eingesetzt werden.</li>\n<li><strong>Integrations- & BSW-Hinweise:</strong></li>\n<li>Die Übersetzung erfolgt vollständig infrastrukturseitig über den BSW-Stack (Com/PduR/Transformer).</li>\n<li><code>SignalServiceTranslationProps</code> definieren die statischen Übersetzungseigenschaften für die Daten- und Signalelemente der beteiligten Schnittstellen.</li>\n<li>Beim Entwurf von AUTOSAR-Systemkonfigurationen ist sicherzustellen, dass Ein- und Ausgangsports typkompatibel zu den jeweiligen <code>SenderReceiverInterface</code>-Definitionen sind.</li>\n</ul>"}, {"id": "FIG-4f7315e03af5c91d", "releases": ["R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Strukturdiagramm / Instanziierungsdiagramm auf M1-Modellebene aus <code>AUTOSAR_TPS_SystemTemplate</code> (Kapitel <em>Signal to Service Translation</em> / <em>System Mapping</em>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation eines rein deklarativen Mappings zur Übersetzung zwischen Signal-basierter Kommunikation (Classic AUTOSAR COM / ISignal / ISignalGroup) und Service-orientierter Kommunikation (SOME/IP, DDS, Adaptive Platform) unter ausschließlicher Verwendung von <code>PassThroughSwConnector</code>-Elementen.</li>\n<li><strong>Architektur-Einordnung:</strong> Zeigt die modellseitige Entkopplung von Übersetzungslogik und Applikationscode. Anstelle einer dedizierten Gateway-/Translation-SW-C mit eigenen <code>RunnableEntity</code>-Instanzen wird die Transformationskapsel als Composition modelliert, deren Ein- und Ausgänge direkt durch BSW-Transformer bzw. Signal-to-Service-Translation-Engines im Basissoftware-Stack verarbeitet werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kapselungskontext / Composite Element:</strong></li>\n<li><code>Signal Service Translation</code>: Repräsentiert die strukturelle Systemgrenze (modelliert als Komposition bzw. Kapselung der Signal-to-Service-Übersetzung).</li>\n<li><strong>Ports (Outer Ports):</strong></li>\n<li><code>R1</code>, <code>R2</code>: <code>RPortPrototype</code> (Required Outer Ports), fungieren als Eingangs-Ports für die zu übersetzenden Quelldaten.</li>\n<li><code>P1</code>, <code>P2</code>: <code>PPortPrototype</code> (Provided Outer Ports), fungieren als Ausgangs-Ports für die transformierten Zieldaten.</li>\n<li><strong>Konnektoren (<code>PassThroughSwConnector</code>):</strong></li>\n<li><code>ptc1</code>: Instanz von <code>PassThroughSwConnector</code></li>\n<li><code>requiredOuterPort: R1</code></li>\n<li><code>providedOuterPort: P1</code></li>\n<li><code>ptc2</code>: Instanz von <code>PassThroughSwConnector</code></li>\n<li><code>requiredOuterPort: R2</code></li>\n<li><code>providedOuterPort: P2</code></li>\n<li><em>Semantik:</em> Verbindet einen äußeren Required-Port direkt mit einem äußeren Provided-Port derselben Komposition, ohne interne <code>SwComponentPrototype</code>-Instanzen zu durchlaufen.</li>\n<li><strong>Schnittstellen & Datenelemente:</strong></li>\n<li><code>S/R Interface ifX</code>: <code>SenderReceiverInterface</code>, typisiert <code>R1</code> und <code>P1</code>. Enthält das aggregierte Datenelement <code>dataX</code> mit den Sub-Elementen/Feldern <code>{A, C}</code>.</li>\n<li><code>S/R Interface ifB</code>: <code>SenderReceiverInterface</code>, typisiert <code>R2</code> und <code>P2</code>. Enthält das Datenelement <code>dataB</code>.</li>\n<li><strong>Transformations-Metadaten (<code>SignalServiceTranslationProps</code> & <code>SignalServiceTranslationEventProps</code>):</strong></li>\n<li>Block <code>X</code> (<code>SignalServiceTranslationProps X</code>, <code>SignalServiceTranslationEventProps X</code>): Konfigurationsklassen zur Definition der Signal-zu-Service- bzw. Event-Übersetzungsregeln, referenzieren über Assoziationspfeile sowohl <code>ifX - dataX {A, C}</code> als auch den Ausgangsport <code>P1</code>.</li>\n<li>Block <code>B</code> (<code>SignalServiceTranslationProps B</code>, <code>SignalServiceTranslationEventProps B</code>): Konfigurationsklassen zur Definition der Übersetzungs- und Event-Eigenschaften, referenzieren über Assoziationspfeile sowohl <code>ifB - dataB</code> als auch den Ausgangsport <code>P2</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Datenfluss:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ingress:</strong> Empfang von Signalen bzw. Service-Events an den Required Outer Ports (<code>R1</code>, <code>R2</code>) aus dem Quellkontext.</li>\n<li><strong>Translation & Transformation (BSW-Ebene):</strong> Die Durchleitung erfolgt über die Pass-Through-Verbindungen <code>ptc1</code> und <code>ptc2</code>. Die eigentliche Signal-zu-Service- bzw. Service-zu-Signal-Übersetzung und Event-Steuerung wird durch die BSW anhand der annotierten Konfigurationsklassen (<code>SignalServiceTranslationProps</code>, <code>SignalServiceTranslationEventProps</code>) für Port <code>P1</code> bzw. <code>P2</code> ausgeführt.</li>\n<li><strong>Egress:</strong> Bereitstellung der transformierten Nutzdaten an den Provided Outer Ports (<code>P1</code>, <code>P2</code>) zur Weiterleitung an die Zielumgebung.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Synchronizität & Scheduling:</strong> Ereignis- oder zyklusgetriebene Verarbeitung auf BSW-Ebene ohne Einbindung applikativer Tasks oder <code>RunnableEntity</code>-Elemente.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Regelwerks-Konformität:</strong> Die Modellierung spezifiziert die Übersetzung zwischen signalbasierter und serviceorientierter Kommunikation rein deklarativ über <code>PassThroughSwConnector</code>-Instanzen und zugeordnete Metadatenklassen.</li>\n<li><strong>Integrations- & BSW-Hinweise:</strong></li>\n<li>Neben statischen Mappings (<code>SignalServiceTranslationProps</code>) erfordern ereignisbasierte Kommunikationsmuster die Spezifikation von <code>SignalServiceTranslationEventProps</code>.</li>\n<li>Die explizite Assoziation der Translation- und Event-Properties auf die Provided Outer Ports (<code>P1</code>, <code>P2</code>) sowie auf die Datenelemente stellt die Zuordnung der Serialisierungs- und Triggermechanismen im BSW-Stack sicher.</li>\n<li>Entwickler müssen sicherstellen, dass die Datenelementstrukturen (<code>dataX</code>, <code>dataB</code>) exakt mit den in den Übersetzungseigenschaften parametrierten Signal- und Service-Payloads übereinstimmen.</li>\n</ul>"}, {"id": "FIG-70c1db874f1dc3ea", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Strukturdiagramm / Instanziierungsdiagramm auf M1-Modellebene aus <code>AUTOSAR_TPS_SystemTemplate</code> (Kapitel <em>Signal to Service Translation</em> / <em>System Mapping</em>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation eines rein deklarativen Mappings zur Übersetzung zwischen Signal-basierter Kommunikation (Classic AUTOSAR COM / ISignal / ISignalGroup) und Service-orientierter Kommunikation (SOME/IP, DDS, Adaptive Platform) unter ausschließlicher Verwendung von <code>PassThroughSwConnector</code>-Elementen.</li>\n<li><strong>Architektur-Einordnung:</strong> Zeigt die modellseitige Entkopplung von Übersetzungslogik und Applikationscode. Anstelle einer dedizierten Gateway-/Translation-SW-C mit eigenen <code>RunnableEntity</code>-Instanzen wird die Transformationskapsel als Composition modelliert, deren Ein- und Ausgänge direkt durch BSW-Transformer bzw. Signal-to-Service-Translation-Engines im Basissoftware-Stack verarbeitet werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kapselungskontext / Composite Element:</strong></li>\n<li><code>Signal Service Translation</code>: Repräsentiert die strukturelle Systemgrenze (modelliert als Komposition bzw. Kapselung der Signal-to-Service-Übersetzung).</li>\n<li><strong>Ports (Outer Ports):</strong></li>\n<li><code>R1</code>, <code>R2</code>: <code>RPortPrototype</code> (Required Outer Ports), fungieren als Eingangs-Ports für die zu übersetzenden Quelldaten.</li>\n<li><code>P1</code>, <code>P2</code>: <code>PPortPrototype</code> (Provided Outer Ports), fungieren als Ausgangs-Ports für die transformierten Zieldaten.</li>\n<li><strong>Konnektoren (<code>PassThroughSwConnector</code>):</strong></li>\n<li><code>ptc1</code>: Instanz von <code>PassThroughSwConnector</code></li>\n<li><code>requiredOuterPort: R1</code></li>\n<li><code>providedOuterPort: P1</code></li>\n<li><code>ptc2</code>: Instanz von <code>PassThroughSwConnector</code></li>\n<li><code>requiredOuterPort: R2</code></li>\n<li><code>providedOuterPort: P2</code></li>\n<li><em>Semantik:</em> Verbindet einen äußeren Required-Port direkt mit einem äußeren Provided-Port derselben Komposition, ohne interne <code>SwComponentPrototype</code>-Instanzen zu durchlaufen.</li>\n<li><strong>Schnittstellen & Datenelemente:</strong></li>\n<li><code>S/R Interface ifX</code>: <code>SenderReceiverInterface</code>, typisiert <code>R1</code> und <code>P1</code>. Enthält das aggregierte Datenelement <code>dataX</code> mit den Sub-Elementen/Feldern <code>{A, C}</code>.</li>\n<li><code>S/R Interface ifB</code>: <code>SenderReceiverInterface</code>, typisiert <code>R2</code> und <code>P2</code>. Enthält das Datenelement <code>dataB</code>.</li>\n<li><strong>Transformations-Metadaten (<code>SignalServiceTranslationProps</code> & <code>SignalServiceTranslationEventProps</code>):</strong></li>\n<li>Block <code>X</code> (<code>SignalServiceTranslationProps X</code>, <code>SignalServiceTranslationEventProps X</code>): Konfigurationsklassen zur Definition der Signal-zu-Service- bzw. Event-Übersetzungsregeln, referenzieren über Assoziationspfeile sowohl <code>ifX - dataX {A, C}</code> als auch den Ausgangsport <code>P1</code>.</li>\n<li>Block <code>B</code> (<code>SignalServiceTranslationProps B</code>, <code>SignalServiceTranslationEventProps B</code>): Konfigurationsklassen zur Definition der Übersetzungs- und Event-Eigenschaften, referenzieren über Assoziationspfeile sowohl <code>ifB - dataB</code> als auch den Ausgangsport <code>P2</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Datenfluss:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ingress:</strong> Empfang von Signalen bzw. Service-Events an den Required Outer Ports (<code>R1</code>, <code>R2</code>) aus dem Quellkontext.</li>\n<li><strong>Translation & Transformation (BSW-Ebene):</strong> Die Durchleitung erfolgt über die Pass-Through-Verbindungen <code>ptc1</code> und <code>ptc2</code>. Die eigentliche Signal-zu-Service- bzw. Service-zu-Signal-Übersetzung und Event-Steuerung wird durch die BSW anhand der annotierten Konfigurationsklassen (<code>SignalServiceTranslationProps</code>, <code>SignalServiceTranslationEventProps</code>) für Port <code>P1</code> bzw. <code>P2</code> ausgeführt.</li>\n<li><strong>Egress:</strong> Bereitstellung der transformierten Nutzdaten an den Provided Outer Ports (<code>P1</code>, <code>P2</code>) zur Weiterleitung an die Zielumgebung.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Synchronizität & Scheduling:</strong> Ereignis- oder zyklusgetriebene Verarbeitung auf BSW-Ebene ohne Einbindung applikativer Tasks oder <code>RunnableEntity</code>-Elemente.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Regelwerks-Konformität:</strong> Die Modellierung spezifiziert die Übersetzung zwischen signalbasierter und serviceorientierter Kommunikation rein deklarativ über <code>PassThroughSwConnector</code>-Instanzen und zugeordnete Metadatenklassen.</li>\n<li><strong>Integrations- & BSW-Hinweise:</strong></li>\n<li>Neben statischen Mappings (<code>SignalServiceTranslationProps</code>) erfordern ereignisbasierte Kommunikationsmuster die Spezifikation von <code>SignalServiceTranslationEventProps</code>.</li>\n<li>Die explizite Assoziation der Translation- und Event-Properties auf die Provided Outer Ports (<code>P1</code>, <code>P2</code>) sowie auf die Datenelemente stellt die Zuordnung der Serialisierungs- und Triggermechanismen im BSW-Stack sicher.</li>\n<li>Entwickler müssen sicherstellen, dass die Datenelementstrukturen (<code>dataX</code>, <code>dataB</code>) exakt mit den in den Übersetzungseigenschaften parametrierten Signal- und Service-Payloads übereinstimmen.</li>\n</ul>"}], "trans": [{"from": "FIG-de406d08ea7bca48", "to": "FIG-4bc59198b9b551de", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4bc59198b9b551de", "to": "FIG-4f7315e03af5c91d", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Datenelemente:</strong> Umbenennung und Restrukturierung von <code>S/R Interface ifY - dataY {B}</code> zu <code>S/R Interface ifB - dataB</code> (Entfall der Sub-Element-Strukturierung <code>{B}</code>).</li>\n<li><strong>Transformations-Metadaten:</strong> Ergänzung von <code>SignalServiceTranslationEventProps X</code> (zusammen mit <code>SignalServiceTranslationProps X</code>) sowie Ersatz von <code>SignalServiceTranslationProps Y</code> durch <code>SignalServiceTranslationProps B</code> und <code>SignalServiceTranslationEventProps B</code>.</li>\n<li><strong>Pfeil- und Referenzierungstopologie:</strong> Die Metadatenblöcke referenzieren nun zusätzlich explizit die Ausgangsports <code>P1</code> bzw. <code>P2</code> über gestrichelte Pfeillinien (statt zuvor ausschließlich durchgezogene Pfeile auf das Interface).</li>\n</ul>"}, {"from": "FIG-4f7315e03af5c91d", "to": "FIG-70c1db874f1dc3ea", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
